#ifndef HB_REGALLOC_H
#define HB_REGALLOC_H

/* MacRunner 2026-08-18, лейн РЕГИСТРЫ — КАРТА ЗАКРЕПЛЕНИЯ РЕГИСТРОВ ГОСТЯ. Ступень Р1.
 *
 * ОДНО место, где записано соответствие «регистр гостя -> регистр хозяина». Всё остальное
 * обязано спрашивать здесь, а не знать номер само: именно рассыпанные по коду константы
 * сделали жёсткий вход связывания `native_code + 12` (hb_runtime.c:4774) и потребовали
 * отдельного гейта, чтобы его снять.
 *
 * ★★★ ПОЧЕМУ ИМЕННО x25-x28 — ЭТО ЗАМЕР, А НЕ ВЫБОР
 *
 * Наряд предлагал карту x9-x15 + x19-x27. Она НЕ ГОДИТСЯ, и обе причины проверены фактом.
 *
 * 1. Закреплённый регистр обязан пережить вызов помощника. Помощники — обычные функции C,
 *    они сохраняют только callee-saved (x19-x28). x9-x15 — caller-saved: помощник затрёт их
 *    молча. Значит кандидаты только из x19-x28, десять штук.
 *
 * 2. Из этих десяти выпуск уже занял шесть. Обследовано ДВУМЯ способами, потому что каждый
 *    поодиночке врёт:
 *
 *    — корпус (tests/hb_regsurvey.c): 274 случая, 19 486 выпущенных слов, разобрано настоящим
 *      дизассемблером (clang -c + otool -tv, не самодельным разбором). Встречаются x0-x6,
 *      x16, x17, x19-x23, x30. Регистры x24-x28 не встретились НИ РАЗУ;
 *
 *    — исходник: x24 ИСПОЛЬЗУЕТСЯ в ДВУХ атомарных путях, оба за
 *      `jit_direct_mem_codegen_enabled` (на x64 выключен, оттого корпус пуст):
 *        `emit_locked_sub_ldxr`  :14342, :14343, :14348 — цикл LDAXR/STLXR для `lock sub`;
 *        `emit_locked_rmw_lse`   :14371, :14375        — копия операнда до инверсии для AND.
 *
 *      ★ ССЫЛКИ ЗДЕСЬ УЖЕ ОДИН РАЗ ПРОТУХЛИ. До 22.08 стояло `:13165` и `:13194` — за четыре
 *      дня файл вырос, и обе строки стали указывать на посторонний код (помощник строковых
 *      операций), то есть ссылка выглядела исправной и указывала не туда. Ссылка на строку —
 *      не доказательство; доказательство это КОМАНДА:
 *          grep -nE '\(out, *(is64, )?(16, )?24[,)]' src/hb_arm64_codegen.c   # ловит оба пути
 *      Полный разбор владения всеми регистрами — reports/ДОГОВОР-РЕГИСТРОВ.md.
 *
 *    Вывод из расхождения: отсутствие в корпусе НЕ доказывает свободу регистра — ровно тот же
 *    класс ошибки, что «маркер не печатается, значит явления нет». Свободными считаются только
 *    те, что не найдены НИ корпусом, НИ чтением исходника.
 *
 *    Свободные callee-saved: x25, x26, x27, x28. Ровно четыре — и ровно столько просит Р2.
 *
 * ★ x18 НЕ БЕРЁМ. На Apple Silicon xnu обнуляет его на любом входе в ядро; у box64 он отдан
 *   под xR8, потому что на Linux свободен. Карту box64 переносить один в один нельзя.
 *
 * ★ ЗАВИСИМОСТЬ, КОТОРУЮ НЕЛЬЗЯ ПОТЕРЯТЬ: СВЯЗЫВАНИЕ БЛОКОВ.
 *   Связывание входит в цель по `MOV X19,X0` (0xAA0003F3), ища его среди ПЕРВЫХ ЧЕТЫРЁХ слов
 *   блока (hb_runtime.c:4812). Закрепление добавляет в пролог два `STP`, и `MOV` уезжает с
 *   12-го байта на 20-й — за пределы окна поиска. Итог: связывание откажется связывать такой
 *   блок (`не связываем`), то есть потеря скорости, а НЕ порча. Отказ безопасный и он
 *   печатается. Оба механизма по умолчанию выключены, так что сегодня они не встречаются;
 *   перед включением обоих сразу окно поиска надо расширить.
 */

/* Номер регистра гостя (hb_reg_t) -> номер регистра хозяина. 0 = НЕ закреплён.
 * Ноль годится как «нет», потому что x0 под закрепление не отдаётся никогда:
 * это первый аргумент, в нём приходит ctx. */
#define HB_SRA_NONE 0

/* Часовой защёлки `hb_codegen_buffer_t::sra_armed`. По образцу HB_RMAP_ARMED: буфер в этом
 * дереве нигде не обнуляется целиком, поэтому голый 0/1 читал бы мусор со стека. */
#define HB_SRA_ARMED 0xA5u

/* Сколько отрезков между вызовами размечаем. Блоков с 10+ вызовами — 1,6 % по замеру на
 * 685 131 настоящем блоке; всё сверх предела обслуживается ГРУБО (выгрузить всё грязное,
 * перечитать всё), то есть верно, просто дороже. Молчаливого усечения нет. */
#define HB_SRA_MAX_SEGMENTS 32

/* Сколько регистров гостя охватывает счёт при выпуске. Ровно HB_REG_RIP из hb_ir.h, но тот
 * заголовок сюда не тянем — значение проверяется статически в hb_arm64_codegen.c. */
#define HB_SRA_COUNT_REGS 17

/* Ступень Р2: четыре самых горячих. Не потому что четыре лучше, а чтобы договоры входа,
 * выхода, помощника и исключения доказывались на малом. */
#define HB_SRA_RAX_HOST 25
#define HB_SRA_RCX_HOST 26
#define HB_SRA_RDX_HOST 27
#define HB_SRA_RSP_HOST 28

/* ★★★ ДВА БАНКА, И ВЫБОР МЕЖДУ НИМИ — ЗАМЕР, А НЕ ВКУС.
 *
 * Регистр под закреплением обязан пережить вызов помощника — но ТОЛЬКО если блок вообще
 * зовёт помощника. Половина блоков не зовёт: замер на 685 131 настоящем блоке даёт
 * **50,9 % блоков без единого вызова**. Такому блоку callee-saved регистр не нужен, и
 * платить за его сохранение (2 команды из 4-5) незачем.
 *
 * Отсюда два банка:
 *
 *   БАНК 0 (блок ЗОВЁТ помощника)  — x25-x28, callee-saved. Блок обязан сохранить их в
 *                                    кадре сам: цена 2 команды на регистр.
 *   БАНК 1 (блок НЕ зовёт)         — x11-x15, caller-saved. Сохранять НЕ НАДО ВОВСЕ:
 *                                    цена 0. Кадр остаётся прежним, 48 байт.
 *
 * Что это даёт (те же 685 131 блок, 37,9 млн команд ARM):
 *
 *   только банк 0 для всех                     1,01 % выпущенного кода
 *   два банка по признаку «зовёт ли»           1,34 %   (+32 %)
 *   сохранение вынесено из блока для всех      2,04 %   (нужен -ffixed на диспетчере)
 *
 * Признак «зовёт ли» берётся не из догадки: `hb_codegen_buffer_t::emitted_call` уже
 * выставляется `emit_blr`, и на него УЖЕ опирается бережливый кадр — причём для более
 * сильного утверждения (там вовсе не сохраняются x19-x23). Опора на него здесь строго
 * слабее, чем уже принятая в дереве.
 *
 * ★ Почему x11-x15, а не x9-x15. Выпуск emits `MOV x9, x20` / `MOV x10, x21` на быстром пути
 *   (записано в комментарии к lean_frame_arm) — x9 и x10 НЕ свободны. Обследование корпуса
 *   их не показало, но исходник показал: тот же случай, что с x24, и тот же вывод —
 *   свободен только тот, кого не нашли НИ корпусом, НИ чтением.
 *
 * ★ Банк 1 и бережливый кадр НЕСОВМЕСТИМЫ: бережливый кадр переселяет x19-x23 именно в
 *   x11-x15. Совмещать нельзя, и это уже обеспечено — закрепление отключено, когда взведён
 *   бережливый кадр. */
#define HB_SRA_BANK_SAVED   0   /* x25-x28, callee-saved, платим за сохранение */
#define HB_SRA_BANK_SCRATCH 1   /* x11-x15, caller-saved, сохранение не нужно */

#define HB_SRA_RAX_HOST_SCRATCH 11
#define HB_SRA_RCX_HOST_SCRATCH 12
#define HB_SRA_RDX_HOST_SCRATCH 13
#define HB_SRA_RSP_HOST_SCRATCH 14

/* Сколько пар STP нужно на сохранение закреплённых в кадре. Четыре регистра = две пары. */
#define HB_SRA_FRAME_EXTRA_BYTES 32

/* Порядок обхода закреплённых — один на весь движок, чтобы пролог и эпилог не разъехались. */
#define HB_SRA_PINNED_LIST(X) \
    X(HB_REG_RAX, HB_SRA_RAX_HOST, HB_SRA_RAX_HOST_SCRATCH)  \
    X(HB_REG_RCX, HB_SRA_RCX_HOST, HB_SRA_RCX_HOST_SCRATCH)  \
    X(HB_REG_RDX, HB_SRA_RDX_HOST, HB_SRA_RDX_HOST_SCRATCH)  \
    X(HB_REG_RSP, HB_SRA_RSP_HOST, HB_SRA_RSP_HOST_SCRATCH)

#endif /* HB_REGALLOC_H */
